create or replace function public.adjust_stock(p_id uuid,p_expected int,p_stock int,p_reason text) returns void language plpgsql security definer set search_path=public as $$
declare v product_variants;begin if not has_permission('content') then raise exception 'Forbidden';end if;if p_stock<0 or length(trim(p_reason))=0 then raise exception 'Invalid stock';end if;select * into v from product_variants where id=p_id for update;if not found then raise exception 'Variant unavailable';end if;if v.stock<>p_expected then raise exception 'Stock changed';end if;update product_variants set stock=p_stock where id=p_id;insert into audit_log(user_id,action,entity_id,details) values(auth.uid(),'adjust_stock',p_id::text,jsonb_build_object('from',v.stock,'to',p_stock,'reason',left(p_reason,200)));end$$;
revoke all on function public.adjust_stock(uuid,int,int,text) from public,anon;
grant execute on function public.adjust_stock(uuid,int,int,text) to authenticated;
create or replace function public.save_box(p_data jsonb) returns uuid language plpgsql security definer set search_path=public as $$
declare v boxes; bid uuid;begin if not has_permission('content') then raise exception 'Forbidden';end if;if trim(coalesce(p_data->>'name_ar',''))='' or (p_data->>'stock')::int<0 or (p_data->>'price')::bigint<0 then raise exception 'Invalid stock';end if;bid:=nullif(p_data->>'id','')::uuid;if bid is null then insert into boxes(name_ar,price,stock,active) values(p_data->>'name_ar',(p_data->>'price')::bigint,(p_data->>'stock')::int,(p_data->>'active')::boolean) returning id into bid;else select * into v from boxes where id=bid for update;if not found then raise exception 'Box unavailable';end if;if v.stock<>(p_data->>'expected_stock')::int then raise exception 'Stock changed';end if;update boxes set name_ar=p_data->>'name_ar',price=(p_data->>'price')::bigint,stock=(p_data->>'stock')::int,active=(p_data->>'active')::boolean where id=bid;end if;insert into audit_log(user_id,action,entity_id) values(auth.uid(),'save_box',bid::text);return bid;end$$;
revoke all on function public.save_box(jsonb) from public,anon;
grant execute on function public.save_box(jsonb) to authenticated;
